import sys, io, base64, re

def main():
    text = sys.stdin.read()
    text = re.sub(r"\s+", "", text)
    if not text:
        print("Error: invalid audio file")
        return
    try:
        raw = base64.b64decode(text, validate=True)
    except Exception:
        print("Error: invalid audio file")
        return
    try:
        import soundfile as sf
        with sf.SoundFile(io.BytesIO(raw)) as f:
            if f.samplerate <= 0:
                raise ValueError
            dur = len(f) / float(f.samplerate)
    except Exception:
        print("Error: invalid audio file")
        return
    print("%.3f" % dur)

main()

