import sys, shlex

def main():
    text = sys.stdin.read()
    try:
        tokens = shlex.split(text)
    except ValueError:
        print("Error: invalid quoting")
        return
    opts = {}
    err = None
    i = 0
    while i < len(tokens):
        t = tokens[i]
        if t.startswith("--"):
            name, eq, val = t.partition("=")
            if name not in ("--input", "--output"):
                err = "Error: unknown option %s" % name
                break
            key = name[2:]
            if eq:
                opts[key] = val
                i += 1
            else:
                if i + 1 >= len(tokens):
                    err = "Error: missing value for %s" % name
                    break
                opts[key] = tokens[i + 1]
                i += 2
        elif t.startswith("-") and len(t) > 1:
            short = t[:2]
            if short not in ("-i", "-o"):
                err = "Error: unknown option %s" % short
                break
            key = "input" if short == "-i" else "output"
            if len(t) > 2:
                opts[key] = t[2:]
                i += 1
            else:
                if i + 1 >= len(tokens):
                    err = "Error: missing value for %s" % short
                    break
                opts[key] = tokens[i + 1]
                i += 2
        else:
            err = "Error: unexpected argument %s" % t
            break
    if err:
        print(err)
    elif "input" not in opts:
        print("Error: missing required option --input")
    else:
        print("input: " + opts["input"])
        print("output: " + opts.get("output", "-"))

main()

