import sys
import click

@click.command()
@click.argument("name")
@click.option("-v", "--verbose", count=True)
def greet(name, verbose):
    click.echo(f"Hello, {name}!")
    if verbose:
        click.echo(f"Verbosity level: {verbose}")

def main():
    tokens = sys.stdin.read().split()
    if not tokens:
        print("Error: missing command")
        return
    if tokens[0] != "greet":
        print(f"Error: unknown command {tokens[0]}")
        return
    rest = tokens[1:]
    seen = 0
    for t in rest:
        if t.startswith("-"):
            if not (t == "--verbose" or (len(t) > 1 and set(t[1:]) == {"v"})):
                print(f"Error: unknown option {t}")
                return
        else:
            seen += 1
            if seen == 2:
                print(f"Error: unexpected argument {t}")
                return
    if seen == 0:
        print("Error: missing required argument NAME")
        return
    try:
        greet.main(args=rest, standalone_mode=False)
    except click.ClickException as e:
        print(f"Error: {e.format_message()}")

main()

