    while lines and lines[-1] == '':
        lines.pop()
    if len(lines) != 2:
        print("Invalid input")
        return
    col, pct_s = lines[0], lines[1]
    if not col.startswith('#'):
        col = '#' + col
    try:
        r, g, b = webcolors.hex_to_rgb(col)
    except Exception:
