import sys
from itertools import combinations

def main():
    lines = sys.stdin.read().split('\n')
    nums = list(map(int, lines[0].split())) if lines else []
    target = 0
    for ln in lines[1:]:
        if ln.strip():
            target = int(ln.strip())
            break
    res = sorted({tuple(sorted(c)) for c in combinations(nums, 3) if sum(c) == target})
    if not res:
        print("No triplets found.")
    else:
        for t in res:
            print(' '.join(map(str, t)))

main()

