import sys
from more_itertools import distinct_combinations

def main():
    data = sys.stdin.read().split('\n')
    if not data or data[0].strip() == '':
        return
    try:
        r = int(data[0].strip())
    except ValueError:
        return
    items = ' '.join(data[1:]).split()
    items.sort()
    if r < 0 or r > len(items):
        return
    if r == 0:
        print('')
        return
    out = []
    for combo in distinct_combinations(items, r):
        out.append(' '.join(combo))
    sys.stdout.write('\n'.join(out) + '\n')

main()

