import sys, json, jwt

def main():
    lines = sys.stdin.read().split("\n")
    secret = lines[0] if lines else ""
    claims = json.loads(lines[1]) if len(lines) > 1 else {}
    token = jwt.encode(claims, secret, algorithm="HS256")
    if isinstance(token, bytes):
        token = token.decode()
    out = [token]
    try:
        n = int(lines[2].strip())
    except Exception:
        n = 0
    for i in range(n):
        t = lines[3 + i] if len(lines) > 3 + i else ""
        try:
            payload = jwt.decode(
                t,
                secret,
                algorithms=["HS256"],
                options={
                    "verify_signature": True,
                    "verify_exp": False,
                    "verify_nbf": False,
                    "verify_iat": False,
                    "verify_aud": False,
                    "verify_iss": False,
                    "require": [],
                },
            )
            if not isinstance(payload, dict):
                raise ValueError
            out.append("VALID " + json.dumps(payload, separators=(",", ":")))
        except Exception:
            out.append("INVALID")
    sys.stdout.write("\n".join(out) + "\n")

main()

