import sys, json
from jsonschema import Draft7Validator

TYPES = ["null", "boolean", "integer", "number", "string", "array", "object"]

def actual(v):
    for t in TYPES:
        if Draft7Validator({"type": t}).is_valid(v):
            return t
    return "unknown"

def main():
    raw = sys.stdin.read()
    lines = raw.split("\n")
    n = int(lines[0].strip())
    specs = []
    for i in range(1, n + 1):
        name, _, t = lines[i].partition(":")
        specs.append((name.strip(), t.strip()))
    payload = "\n".join(lines[n + 1:])
    try:
        if not payload.strip():
            raise ValueError
        data = json.loads(payload)
    except Exception:
        print("ERROR: invalid JSON")
        return
    if not Draft7Validator({"type": "object"}).is_valid(data):
        print("ERROR: payload is not an object")
        return
    out = []
    for name, t in specs:
        if name not in data:
            out.append("MISSING: %s" % name)
        elif not Draft7Validator({"type": t}).is_valid(data[name]):
            out.append("TYPE: %s expected %s got %s" % (name, t, actual(data[name])))
    print("\n".join(out) if out else "VALID")

main()

