import sys, json
from datetime import date
from pydantic import BaseModel, ValidationError, field_validator, ConfigDict

ORDER = ["name", "age", "signup_date", "tags"]

class Req(BaseModel):
    model_config = ConfigDict(strict=True, extra="ignore")
    name: str
    age: int
    signup_date: str
    tags: list[str] = []

    @field_validator("name")
    @classmethod
    def v_name(cls, v):
        v = v.strip()
        if not v:
            raise ValueError("must not be empty")
        return v

    @field_validator("age")
    @classmethod
    def v_age(cls, v):
        if not (0 <= v <= 130):
            raise ValueError("out of range")
        return v

    @field_validator("signup_date")
    @classmethod
    def v_date(cls, v):
        try:
            d = date.fromisoformat(v)
        except ValueError:
            raise ValueError("not a valid date")
        if d.isoformat() != v:
            raise ValueError("not a valid date")
        return v

def main():
    raw = sys.stdin.read()
    try:
        data = json.loads(raw)
    except Exception:
        print("ValidationError: input: not a JSON object")
        return
    if not isinstance(data, dict):
        print("ValidationError: input: not a JSON object")
        return
    try:
        m = Req(**data)
    except ValidationError as e:
        errs = {}
        for err in e.errors():
            loc = err["loc"][0] if err["loc"] else "input"
            if loc in errs:
                continue
            t = err["type"]
            if t == "missing":
                msg = "field required"
            elif t.endswith("_type"):
                msg = "wrong type"
            else:
                msg = err["msg"].replace("Value error, ", "")
            errs[loc] = msg
        for f in ORDER:
            if f in errs:
                print("ValidationError: %s: %s" % (f, errs[f]))
                return
        print("ValidationError: input: not a JSON object")
        return
    print(json.dumps({"name": m.name, "age": m.age, "signup_date": m.signup_date, "tags": m.tags}))

main()

