import sys
from datetime import timezone
from dateutil import parser as dp

def main():
    lines = [l.strip() for l in sys.stdin.read().splitlines() if l.strip()]
    if len(lines) != 2:
        print("Invalid input")
        return
    try:
        a = dp.isoparse(lines[0])
        b = dp.isoparse(lines[1])
    except (ValueError, OverflowError):
        print("Invalid input")
        return
    if a.tzinfo is None:
        a = a.replace(tzinfo=timezone.utc)
    if b.tzinfo is None:
        b = b.replace(tzinfo=timezone.utc)
    d = (a - b).total_seconds()
    n = int(d)  # truncate toward zero
    if n > 0:
        print(f"{n} seconds ago")
    elif n < 0:
        print(f"in {-n} seconds")
    else:
        print("0 seconds ago")

main()

