import sys, re, calendar
from dateutil.parser import parse

FULL = {m.lower() for m in calendar.month_name if m}
ABBR = {m.lower() for m in calendar.month_abbr if m}
NAMES = FULL | ABBR

def try_parse(s):
    try:
        if re.fullmatch(r'\d{4}-\d{2}-\d{2}', s):
            return parse(s)
        if re.fullmatch(r'\d{2}/\d{2}/\d{4}', s):
            return parse(s, dayfirst=True)
        m = re.fullmatch(r'([A-Za-z]+) (\d{1,2}), (\d{4})', s)
        if m and m.group(1).lower() in NAMES:
            return parse(s)
        m = re.fullmatch(r'(\d{1,2}) ([A-Za-z]+) (\d{4})', s)
        if m and m.group(2).lower() in NAMES:
            return parse(s)
    except (ValueError, OverflowError):
        return None
    return None

days = ['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday']
counts = {d: 0 for d in days}
bad = 0
for line in sys.stdin.read().splitlines():
    s = line.strip()
    if not s:
        continue
    d = try_parse(s)
    if d is None:
        bad += 1
    else:
        counts[days[d.weekday()]] += 1
for d in days:
    print(f"{d}: {counts[d]}")
print(f"Unparsed: {bad}")

