import sys, io, json, re
from dotenv import dotenv_values

text = sys.stdin.read()
vals = dotenv_values(stream=io.StringIO(text))

SECRET = ("PASSWORD", "SECRET", "TOKEN", "API_KEY")
INT_RE = re.compile(r'^[+-]?\d+$')
FLOAT_RE = re.compile(r'^[+-]?(\d+\.\d*|\.\d+|\d+)([eE][+-]?\d+)?$')

cfg = {}
for k, v in vals.items():
    if v is None:
        continue
    up = k.upper()
    if any(s in up for s in SECRET):
        cfg[k] = "***"
        continue
    low = v.lower()
    if low == "true":
        cfg[k] = True
    elif low == "false":
        cfg[k] = False
    elif INT_RE.match(v):
        cfg[k] = int(v)
    elif FLOAT_RE.match(v):
        cfg[k] = float(v)
    else:
        cfg[k] = v

print(json.dumps({k: cfg[k] for k in sorted(cfg)}, indent=2))

