import sys
import orjson

def main():
    raw = sys.stdin.buffer.read()
    text = raw.decode('utf-8', 'replace').strip()
    err = "Error: invalid input."
    if not text:
        print(err); return
    try:
        recs = orjson.loads(text)
    except Exception:
        print(err); return
    if not isinstance(recs, list):
        print(err); return
    for r in recs:
        if not isinstance(r, dict):
            print(err); return
        for k, v in r.items():
            if not isinstance(k, str):
                print(err); return
            if not (v is None or isinstance(v, (str, bool, int))) or isinstance(v, float):
                print(err); return
    blob = orjson.dumps(recs, option=orjson.OPT_SORT_KEYS)
    back = orjson.loads(blob)
    out = [str(len(back))]
    for r in back:
        out.append(orjson.dumps(r, option=orjson.OPT_SORT_KEYS).decode('utf-8'))
    sys.stdout.write("\n".join(out) + "\n")

main()

