    if not (x.notna().all() and y.notna().all()):
        print("Error: invalid input"); return

    def z(s):
        sd = s.std(ddof=0)
        if sd == 0:
            return s * 0.0
        return (s - s.mean()) / sd

    out = pd.DataFrame({"label": df[cols[0]], "z1": z(x), "z2": z(y)})
    out["gap"] = (out["z1"] - out["z2"]).abs()
    out["ord"] = range(len(out))
    out = out.sort_values(["gap", "ord"], ascending=[False, True]).head(k)
    print("label,z1,z2,gap")
    for r in out.itertuples():
        print(f"{r.label},{fmt(r.z1)},{fmt(r.z2)},{fmt(r.gap)}")

main()

