import sys

def parse(lines):
    d = {}
    for raw in lines:
        s = raw.strip()
        if not s:
            continue
        parts = s.split()
        if len(parts) != 2:
            continue
        d[parts[0]] = parts[1]
    return d

def main():
    lines = sys.stdin.read().split('\n')
    sep = None
    for i, l in enumerate(lines):
        if l.strip() == '---':
            sep = i
            break
    if sep is None:
        print('Error: missing snapshot separator.')
        return
    before = parse(lines[:sep])
    after = parse(lines[sep+1:])
    events = []
    for p in after:
        if p not in before:
            events.append((p, 'Created'))
        elif before[p] != after[p]:
            events.append((p, 'Modified'))
    for p in before:
        if p not in after:
            events.append((p, 'Deleted'))
    if not events:
        print('No changes')
        return
    for p, k in sorted(events):
        print('%s: %s' % (k, p))

main()

