import sys
from watchdog.events import (FileSystemEventHandler, FileModifiedEvent,
                              FileCreatedEvent, FileDeletedEvent, FileMovedEvent)


def main():
    lines = sys.stdin.read().splitlines()
    if not lines or not lines[0].strip():
        print("No changes detected.")
        return
    target = lines[0].strip()
    hits = []

    class Handler(FileSystemEventHandler):
        def on_modified(self, event):
            if not event.is_directory and event.src_path == target:
                hits.append(event.src_path)

    handler = Handler()
    for line in lines[1:]:
        parts = line.split()
        if not parts:
            continue
        kind = parts[0]
        if kind == "moved":
            if len(parts) != 3:
                continue
            event = FileMovedEvent(parts[1], parts[2])
        elif len(parts) != 2:
            continue
        elif kind == "modified":
            event = FileModifiedEvent(parts[1])
        elif kind == "created":
            event = FileCreatedEvent(parts[1])
        elif kind == "deleted":
            event = FileDeletedEvent(parts[1])
        else:
            continue
        handler.dispatch(event)

    if not hits:
        print("No changes detected.")
    else:
        for path in hits:
            print("File modified: " + path)


main()

