    try:
        vals = [int(t) for t in toks]
        mw, mh, w, h = vals[0], vals[1], vals[2], vals[3]
        if min(mw, mh, w, h) < 1 or len(vals) != 4 + w * h:
            raise ValueError
        px = np.array(vals[4:], dtype=int).reshape(h, w)
        if px.min() < 0 or px.max() > 255:
            raise ValueError
