        nw, nh = w, h
    elif mw * h <= mh * w:
        nw, nh = mw, max(1, (h * mw) // w)
    else:
        nh, nw = mh, max(1, (w * mh) // h)
    xi = np.minimum(((np.arange(nw) + 0.5) * w / nw).astype(int), w - 1)
    yi = np.minimum(((np.arange(nh) + 0.5) * h / nh).astype(int), h - 1)
