import sys, re
from netaddr import IPAddress, IPNetwork

V4 = re.compile(r'^(25[0-5]|2[0-4][0-9]|1[0-9][0-9]|[1-9]?[0-9])(\.(25[0-5]|2[0-4][0-9]|1[0-9][0-9]|[1-9]?[0-9])){3}$')

def parse(s):
    if V4.match(s):
        return IPAddress(s, 4)
    try:
        a = IPAddress(s, 6)
        if a.version == 6:
            return a
    except Exception:
        pass
    return None

def main():
    lines = sys.stdin.read().splitlines()
    if not lines:
        print("Invalid CIDR")
        return
    cidr = lines[0].strip()
    if '/' in cidr:
        ipart, _, pl = cidr.partition('/')
    else:
        ipart, pl = cidr, None
    base = parse(ipart)
    if base is None or (pl is not None and not pl.isdigit()):
        print("Invalid CIDR")
        return
    maxlen = 32 if base.version == 4 else 128
    p = maxlen if pl is None else int(pl)
    if p > maxlen:
        print("Invalid CIDR")
        return
    net = IPNetwork("%s/%d" % (base, p)).cidr
    out = []
    for line in lines[1:]:
        s = line.strip()
        if not s:
            continue
        ip = parse(s)
        if ip is None:
            out.append("INVALID")
        elif ip.version == net.version and net.first <= int(ip) <= net.last:
            out.append("True")
        else:
            out.append("False")
    sys.stdout.write("".join(x + "\n" for x in out))

main()

