import sys, json, re
from jsonschema import Draft7Validator

def esc(p):
    return str(p).replace('~', '~0').replace('/', '~1')

def main():
    text = sys.stdin.read()
    parts = re.split(r'(?m)^---[ \t]*$', text)
    if len(parts) != 2:
        print("Error: invalid input"); return
    try:
        schema = json.loads(parts[0])
        config = json.loads(parts[1])
    except Exception:
        print("Error: invalid input"); return
    errors = list(Draft7Validator(schema).iter_errors(config))
    if not errors:
        print("valid"); return

    def doc_key(path):
        key = []
        node = config
        for p in path:
            if isinstance(node, dict):
                ks = list(node.keys())
                key.append(ks.index(p) if p in node else len(ks))
                node = node.get(p)
            elif isinstance(node, list):
                key.append(p if isinstance(p, int) else 0)
                node = node[p] if isinstance(p, int) and p < len(node) else None
            else:
                key.append(0)
        return key

    errors.sort(key=lambda e: (doc_key(list(e.absolute_path)), e.validator))
    e = errors[0]
    ptr = ''.join('/' + esc(p) for p in e.absolute_path)
    if e.validator == 'required':
        m = re.match(r"'(.*)' is a required property", e.message)
        if m:
            ptr = ptr + '/' + esc(m.group(1))
    print("invalid")
    print("%s: %s" % (ptr, e.validator))

main()

