    arr = np.array(rows, dtype=float)
    ti = header.index(target)
    y = arr[:, ti]
    X = np.delete(arr, ti, axis=1)
    if X.shape[1] == 0:
        pred = np.full_like(y, y.mean())
    else:
        pred = LinearRegression().fit(X, y).predict(X)
    for r in y - pred:
        v = round(float(r), 4)
