import sys
from tenacity import Retrying, stop_after_attempt, wait_exponential

def main():
    lines = sys.stdin.read().splitlines()
    try:
        base = float(lines[0].strip())
        n = int(lines[1].strip())
        if base < 0 or n < 0 or len(lines) < 2 + n:
            raise ValueError
        codes = [int(lines[2 + i].strip()) for i in range(n)]
    except Exception:
        print("Invalid input")
        return

    out = []
    state = {"i": 0, "k": 0, "ok": 0}

    def sleeper(d):
        out.append("Retrying in %.3f seconds" % d)

    def call():
        state["k"] += 1
        k = state["k"]
        if state["i"] < len(codes):
            c = codes[state["i"]]
            state["i"] += 1
            out.append("Attempt %d: %d" % (k, c))
            if 200 <= c <= 299:
                state["ok"] = k
                return
        else:
            out.append("Attempt %d: ERROR" % k)
        raise RuntimeError("fail")

    try:
        for attempt in Retrying(stop=stop_after_attempt(5),
                                wait=wait_exponential(multiplier=base, exp_base=2, min=0),
                                sleep=sleeper, reraise=True):
            with attempt:
                call()
    except RuntimeError:
        pass

    if out:
        print("\n".join(out))
    if state["ok"]:
        print("Succeeded on attempt %d" % state["ok"])
    else:
        print("Giving up after 5 attempts")

main()

