import sys
from tenacity import Retrying, stop_after_attempt, retry_if_exception_type

class Transient(Exception):
    def __init__(self, name):
        super().__init__(name); self.name = name

class Permanent(Exception):
    def __init__(self, name):
        super().__init__(name); self.name = name

class NoOutcome(Exception):
    pass

def main():
    lines = sys.stdin.read().split("\n")
    while lines and lines[-1].strip() == "":
        lines.pop()
    if len(lines) < 4:
        print("Error: invalid input"); return
    try:
        p = lines[0].split()
        if len(p) != 4: raise ValueError
        n = int(p[0]); base = float(p[1]); mult = float(p[2]); cap = float(p[3])
        if n < 1 or min(base, mult, cap) < 0: raise ValueError
        transient = set(lines[1].split())
        fr = [float(x) for x in lines[2].split()]
        if not fr or any(f < 0 or f > 1 for f in fr): raise ValueError
        outs = []
        for ln in lines[3:]:
            t = ln.split(None, 1)
            if not t: raise ValueError
            if t[0] == "OK":
                if len(t) < 2 or not t[1].strip(): raise ValueError
                outs.append(("OK", t[1].strip()))
            elif t[0] == "ERR":
                if len(t) < 2 or len(t[1].split()) != 1: raise ValueError
                outs.append(("ERR", t[1].strip()))
            else:
                raise ValueError
    except ValueError:
        print("Error: invalid input"); return

    it = iter(outs); cnt = [0]; total = [0.0]

    def wait(rs):
        k = rs.attempt_number
        b = min(cap, base * (mult ** (k - 1)))
        return round(b * fr[(k - 1) % len(fr)], 3)

    def sleep(d):
        total[0] += d
        print("sleep %.3f" % d)

    def call():
        o = next(it, None)
        if o is None: raise NoOutcome
        cnt[0] += 1
        if o[0] == "OK":
            print("attempt %d: ok %s" % (cnt[0], o[1])); return o[1]
        print("attempt %d: error %s" % (cnt[0], o[1]))
        if o[1] in transient: raise Transient(o[1])
        raise Permanent(o[1])

    try:
        v = Retrying(stop=stop_after_attempt(n), wait=wait, sleep=sleep,
                     retry=retry_if_exception_type(Transient), reraise=True)(call)
        print("result: " + v)
    except Transient as e:
        print("gave up: " + e.name)
    except Permanent as e:
        print("failed: " + e.name)
    except NoOutcome:
        print("Error: insufficient outcomes"); return
    print("total sleep: %.3f" % total[0])

main()

