import sys, re
from sqlalchemy import create_engine, MetaData, Table, Column, Integer, Text, Float, select, insert

def main():
    lines = sys.stdin.read().split("\n")
    if lines and lines[-1] == "":
        lines.pop()
    ident = re.compile(r'[A-Za-z_][A-Za-z0-9_]*$')
    def bad():
        print("Error: invalid schema")
        sys.exit(0)
    if len(lines) < 2:
        bad()
    tname = lines[0].strip()
    if not ident.match(tname):
        bad()
    if lines[1].strip() == "":
        bad()
    cols = []
    for spec in lines[1].split(","):
        parts = spec.split(":")
        if len(parts) != 2:
            bad()
        n = parts[0].strip(); t = parts[1].strip()
        if not ident.match(n) or t not in ("INTEGER", "TEXT", "REAL"):
            bad()
        cols.append((n, t))
    names = [c[0] for c in cols]
    if len(set(names)) != len(names):
        bad()
    tm = {"INTEGER": Integer, "TEXT": Text, "REAL": Float}
    md = MetaData()
    tbl = Table(tname, md, *[Column(n, tm[t], primary_key=(i == 0))
                             for i, (n, t) in enumerate(cols)])
    eng = create_engine("sqlite://")
    md.create_all(eng)
    intre = re.compile(r'[+-]?\d+$')
    realre = re.compile(r'[+-]?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$')
    report = []; rows = []; seen = set(); idx = 0
    for raw in lines[2:]:
        if raw.strip() == "":
            continue
        idx += 1
        f = [x.strip() for x in raw.split("|")]
        if len(f) != len(cols):
            report.append("%d: rejected (field count)" % idx); continue
        if f[0] == "":
            report.append("%d: rejected (empty key)" % idx); continue
        vals = {}; err = None
        for (n, t), v in zip(cols, f):
            if t == "INTEGER":
                if not intre.match(v):
                    err = "invalid INTEGER in %s" % n; break
                vals[n] = int(v)
            elif t == "REAL":
                if not realre.match(v):
                    err = "invalid REAL in %s" % n; break
                vals[n] = float(v)
            else:
                vals[n] = v
        if err:
            report.append("%d: rejected (%s)" % (idx, err)); continue
        k = vals[names[0]]
        if k in seen:
            report.append("%d: rejected (duplicate key)" % idx); continue
        seen.add(k); rows.append(vals)
        report.append("%d: inserted" % idx)
    with eng.begin() as conn:
        if rows:
            conn.execute(insert(tbl), rows)
    out = list(report)
    out.append("")
    out.append(",".join(names))
    with eng.connect() as conn:
        for r in conn.execute(select(tbl).order_by(tbl.c[names[0]])):
            cells = []
            for (n, t), v in zip(cols, r):
                if t == "INTEGER":
                    cells.append(str(int(v)))
                elif t == "REAL":
                    cells.append("%.6f" % v)
                else:
                    cells.append(str(v))
            out.append(",".join(cells))
    print("\n".join(out))

main()

