import sys, json
from deepdiff import DeepDiff

MARK = '\x00LIST\x00'

def render(v):
    return json.dumps(v, ensure_ascii=False, separators=(',', ':'))

def enc(v):
    if isinstance(v, dict):
        return {k: enc(x) for k, x in v.items()}
    if isinstance(v, list):
        return MARK + render(v)
    return v

def dec(v):
    if isinstance(v, dict):
        return {k: dec(x) for k, x in v.items()}
    if isinstance(v, str) and v.startswith(MARK):
        return json.loads(v[len(MARK):])
    return v

def show(v):
    return render(dec(v))

def main():
    data = sys.stdin.read()
    lines = data.split('\n')
    idx = None
    for i, l in enumerate(lines):
        if l.strip() == '---':
            idx = i
            break
    if idx is None:
        print('Error: invalid input')
        return
    a = '\n'.join(lines[:idx])
    b = '\n'.join(lines[idx+1:])
    try:
        old = json.loads(a)
        new = json.loads(b)
    except Exception:
        print('Error: invalid input')
        return
    if not isinstance(old, dict) or not isinstance(new, dict):
        print('Error: invalid input')
        return
    d = DeepDiff(enc(old), enc(new), view='tree')
    rows = []
    for t in d.get('dictionary_item_added', []):
        p = '.'.join(str(x) for x in t.path(output_format='list'))
        rows.append((p, 'added %s: %s' % (p, show(t.t2))))
    for t in d.get('dictionary_item_removed', []):
        p = '.'.join(str(x) for x in t.path(output_format='list'))
        rows.append((p, 'removed %s: %s' % (p, show(t.t1))))
    for key in ('values_changed', 'type_changes'):
        for t in d.get(key, []):
            p = '.'.join(str(x) for x in t.path(output_format='list'))
            rows.append((p, 'changed %s: %s -> %s' % (p, show(t.t1), show(t.t2))))
    if not rows:
        print('No changes')
        return
    for _, line in sorted(rows, key=lambda r: r[0]):
        print(line)

main()

