import sys, re, structlog

INT = re.compile(r'^-?(0|[1-9][0-9]*)$')
LEVELS = {"debug", "info", "warning", "error", "critical"}

def conv(v):
    if v == "true": return True
    if v == "false": return False
    if v == "null": return None
    if INT.match(v): return int(v)
    return v

def fields(s):
    d = {}
    for tok in s.split():
        if "=" in tok:
            k, v = tok.split("=", 1)
            if k:
                d[k] = conv(v)
    return d

lines = sys.stdin.read().split("\n")
if lines and lines[-1] == "":
    lines.pop()
if not lines:
    sys.exit()

structlog.configure(
    processors=[structlog.processors.JSONRenderer(sort_keys=True)],
    logger_factory=structlog.PrintLoggerFactory(),
)
log = structlog.get_logger().bind(**fields(lines[0]))

for line in lines[1:]:
    if ":" not in line:
        continue
    lvl, rest = line.split(":", 1)
    lvl = lvl.strip().lower()
    if lvl not in LEVELS:
        continue
    msg, _, fp = rest.partition(" | ")
    log.bind(**fields(fp)).msg(msg.strip(), level=lvl)

