import sys
import pandas as pd
import pytz


def main():
    text = sys.stdin.read()
    lines = text.split("\n")
    tz = lines[0].strip() if lines else ""
    try:
        zone = pytz.timezone(tz)
    except Exception:
        print(("Invalid timezone: " + tz).rstrip())
        return
    counts = {}
    for raw in lines[1:]:
        s = raw.strip()
        if not s:
            continue
        try:
            ts = pd.Timestamp(s)
            if ts is pd.NaT:
                raise ValueError
        except Exception:
            continue
        if ts.tzinfo is None:
            ts = ts.tz_localize("UTC")
        h = ts.tz_convert(zone).hour
        counts[h] = counts.get(h, 0) + 1
    if not counts:
        print("No valid timestamps.")
        return
    for h in sorted(counts):
        print("%02d %d" % (h, counts[h]))


main()

