import sys
from pint import UnitRegistry

ALLOWED = {'m','km','cm','mm','in','ft','yd','mi','g','kg','mg','lb','oz','s','ms','min','h','day'}
ureg = UnitRegistry()

lines = [l for l in sys.stdin.read().splitlines() if l.strip()]
if len(lines) != 2:
    print("Error: invalid input"); sys.exit()

qs = []
ok = True
for line in lines:
    parts = line.split()
    if len(parts) != 2 or parts[1] not in ALLOWED:
        ok = False; break
    try:
        val = float(parts[0])
    except ValueError:
        ok = False; break
    qs.append(ureg.Quantity(val, parts[1]))
if not ok:
    print("Error: invalid input"); sys.exit()

try:
    r = (qs[0] + qs[1]).to(qs[0].units)
except Exception:
    print("Error: incompatible units"); sys.exit()

s = f"{r.magnitude:.6f}".rstrip('0').rstrip('.')
if float(s) == 0:
    s = "0"
print(f"{s} {lines[0].split()[1]}")

