import sys
from lxml import etree

data = sys.stdin.read()
parts = data.split('\n', 1)
name = parts[0].strip()
doc = parts[1] if len(parts) > 1 else ''

if not name:
    print('Error: missing element name')
    sys.exit()

try:
    root = etree.fromstring(doc.encode('utf-8'))
except Exception:
    print('Error: invalid XML')
    sys.exit()

found = []
for el in root.iter():
    if isinstance(el.tag, str) and el.tag == name:
        found.append((el.text or '').strip())

if not found:
    print('Element not found: ' + name)
else:
    for t in found:
        print(t)

