import sys, re, json
import yaml

def fail():
    print("Error: invalid configuration.")
    sys.exit(0)

def merge(base, over):
    out = dict(base)
    for k, v in over.items():
        if k in out and isinstance(out[k], dict) and isinstance(v, dict):
            out[k] = merge(out[k], v)
        else:
            out[k] = v
    return out

text = sys.stdin.read()
parts = re.split(r'(?m)^---[ \t]*$\n?', text)
if len(parts) != 2:
    fail()
try:
    base = yaml.safe_load(parts[0])
    over = yaml.safe_load(parts[1])
except Exception:
    fail()
if base is None:
    base = {}
if over is None:
    over = {}
if not isinstance(base, dict) or not isinstance(over, dict):
    fail()
print(json.dumps(merge(base, over), indent=2, sort_keys=True, ensure_ascii=False))
